  const currentValue = normalizeText($span.text());
  if (currentValue !== 'Default Tesoreria') {
    cy.get('button[class="btn dropdown-toggle btn-default btn-sm selectpicker"]').click();
    cy.contains(/^Default Tesorer[íi]a|Default Tesorerï¿½a$/).click();
